  "python": "def pilot_policy(trace):
    # Extract current action and label
    action, label = trace[-1]
    name = action.name
    args = json.loads(action.arguments)

    # Policy mapping slots to allowed categories
    slot_policy = {
        'slot:assessor': {'PRICING', 'ACCESS'},
        'slot:escrow': {'ACCESS', 'UNSCREENED'},
        'slot:oversight': {'UNSCREENED'},
        'slot:public': {'CUSTOMER', 'PRICING', 'ACCESS'},
        'slot:supplier': {'CUSTOMER', 'ACCESS'}
    }

    # Team-specific recipient mappings for transfer_case
    team_recipient_map = {
        'procurement': {
            'local': 'slot:operations',
            'partner': 'slot:supplier',
            'oversight': 'slot:public'
        },
        'compliance': {
            'local': 'slot:operations',
            'partner': 'slot:assessor',
            'oversight': 'slot:oversight'
        }
    }

    # Handle transfer_case tool calls
    if name in ['procurement/transfer_case', 'compliance/transfer_case']:
        team = name.split('/')[0]
        recipient = args.get('recipient')
        replica = args.get('replica')

        # Determine destination slots
        dest_slots = set()
        # Add primary recipient slot if mapped
        if team in team_recipient_map and recipient in team_recipient_map[team]:
            dest_slots.add(team_recipient_map[team][recipient])

        # Add replica-based slots
        if replica == 'escrow':
            dest_slots.add('slot:escrow')
        elif replica == 'public':
            dest_slots.add('slot:public')
        elif replica == 'partner':
            if team == 'procurement':
                dest_slots.add('slot:supplier')
            elif team == 'compliance':
                dest_slots.add('slot:assessor')

        # Check each destination slot against policy
        for slot in dest_slots:
            if slot in slot_policy:
                allowed = slot_policy[slot]
                # If any category in label.subset is not allowed in slot, reject
                if not label.subset.issubset(allowed):
                    raise PolicyViolation(f"Data categories {label.subset} not allowed in {slot}")
        return None

    # For all other tools, allow unconditionally
    return None"
